example.nonCompliant:
async function getUser() {
  const res = await api.getUser();
  return res.name;
}

example.compliant:
async function getUser() {
  const res = await api.getUser();
  if (!res) throw new Error('Null or undefined response');
  return res?.name ?? 'Anonymous';
}

getUsers() {
  return this.http.get<User[]>('/api/users').pipe(
    map(res => res ?? []),
    map(users => users?.map(u => u?.name ?? 'Unknown')),
    catchError(() => of([]))
  );
}
